import {crew} from './core.mjs';
import {proofIsCurrent} from './operations.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const portrait=(i,size='')=>`<span class="human-portrait human-${i} ${size}" role="img" aria-label="${crew[i]?.name||'AI specialist'} · fictional AI persona"></span>`;
const boundaries=['I cannot establish access from a payment alone.','I cannot prove a root cause that the records don’t show.','I never approve my own correction or change a payment.','I keep the case open when an outcome check fails.'];
export function guideStep(s){
 if(!s)return {agent:0,title:'Start with one customer.',body:'Choose a case from Needs attention, or open Investigating to review a purchase. We’ll explain each step as you go.',target:null};
 if(s.job?.pending)return {agent:1,title:'The workflow is still running.',body:'Use Refresh workflow status to retrieve the server result. Nothing in this guide advances the workflow.',target:null};
 if(proofIsCurrent(s))return {agent:3,title:'Now you have a checked outcome.',body:'Review the passed checks, download the receipt, and review the customer reply before copying it. Nothing is sent automatically.',target:'Customer reply'};
 if(['unverified','verifying','verify-only','verified'].includes(s.phase))return {agent:3,title:'Check the outcome, not just the update.',body:'Use the verification action below. If a read fails, the case stays open; retrying verification does not grant access again.',target:'Recovery timeline'};
 if(s.phase==='approved')return {agent:2,title:'Your approval is recorded.',body:'The change has not been applied yet. Check the exact customer and course, then choose Apply & verify access when you’re ready.',target:'Purchase evidence'};
 if(s.phase==='rehearsed')return {agent:2,title:'You make the decision.',body:'Compare before and after. If the proposed grant is correct, check the consent box and approve it. Approval and execution are separate actions.',target:'Purchase evidence'};
 if(s.phase==='investigated')return {agent:2,title:'Preview the smallest useful fix.',body:'Read the recommendation and its limitations. Preview correction creates a rehearsal copy; it does not change the customer’s access.',target:'Specialist review'};
 if(['blocked','needs-evidence','stale'].includes(s.phase))return {agent:3,title:'Pause here. The evidence needs attention.',body:'Inspect the purchase evidence and open objections. Do not grant access while the records are missing, contradictory, or out of date.',target:'Purchase evidence'};
 return {agent:0,title:'First, prove the purchase match.',body:'Review purchase evidence checks the payment, order, customer, course, amount, and currency. A completed payment alone is not enough.',target:'Purchase evidence'};
}
let dialog,callbacks,opener;
function closeDialog(){dialog.close();opener?.isConnected&&opener.focus();}
function openDialog(html){if(!dialog){dialog=document.createElement('dialog');dialog.className='guide-dialog';dialog.setAttribute('aria-labelledby','guide-title');document.body.append(dialog);dialog.addEventListener('click',event=>{if(event.target===dialog)closeDialog();});dialog.addEventListener('cancel',()=>{opener?.isConnected&&opener.focus();});}if(!dialog.open)opener=document.activeElement;dialog.innerHTML=`<button class="dialog-close" aria-label="Close dialog">×</button>${html}`;dialog.querySelector('.dialog-close').onclick=closeDialog;if(!dialog.open)dialog.showModal();}
function profile(i){const a=crew[i];openDialog(`<div class="profile-hero">${portrait(i,'profile-portrait')}<div><span class="eyebrow">YOUR AI SPECIALIST</span><h2 id="guide-title">Meet ${a.name}.</h2><p>${a.role}</p><span class="persona-chip">${a.trait}</span></div></div><blockquote>“${a.hello}”</blockquote><div class="profile-scope"><h3>What I bring to the case</h3><p>${a.scope}</p><h3>My boundary</h3><p>${boundaries[i]}</p></div><p class="persona-note">Fictional AI persona. Human-style portrait, not a human support representative. Public-demo consultations are scripted.</p><button class="button primary" data-close-profile>Back to workspace</button>`);dialog.querySelector('[data-close-profile]').onclick=closeDialog;}
const tour=[
 {i:0,kicker:'01 / FIND YOUR NEXT CASE',title:'One customer. One clear next step.',text:'The recovery queue separates cases needing your attention, purchases awaiting investigation, and verified recoveries. Start with the suggested case or choose your own.',preview:'Needs attention → Investigating → Resolved'},
 {i:0,kicker:'02 / CHECK THE EVIDENCE',title:'Let’s start with what we know.',text:'Ledger checks the purchase match. Relay follows the store’s event trail. Open Purchase evidence and Specialist review to inspect records, explanations, and what remains uncertain.',preview:'Payment + order + customer + course'},
 {i:2,kicker:'03 / PREVIEW & APPROVE',title:'Your decision comes first.',text:'Patch proposes the smallest correction. Preview it without changing access, then use the explicit consent checkbox if you agree. The tour never approves or applies anything.',preview:'Preview → your approval → separate execution'},
 {i:3,kicker:'04 / VERIFY THE OUTCOME',title:'A successful update isn’t the finish.',text:'Prism checks the outcome. A case closes only when payment, access, and lesson checks agree. Failed verification remains open and can be retried without another grant.',preview:'Grant recorded ≠ access verified'},
 {i:1,kicker:'05 / YOU’RE READY',title:'Want us beside you as you go?',text:'Enable guided mode for short, case-specific explanations above each review. You can turn it off at any time. All actions stay under your control.',preview:'Guidance explains. You decide.'}
];
function showTour(index=0){const t=tour[index];openDialog(`<div class="tour-person">${portrait(t.i)}<span><strong>${crew[t.i].name}</strong><small>AI specialist · walkthrough</small></span></div><div class="eyebrow">${t.kicker}</div><h2 id="guide-title">${t.title}</h2><p class="tour-copy">${t.text}</p><div class="tour-preview">${t.preview}</div><div class="tour-bottom"><span class="tour-dots" aria-label="Step ${index+1} of 5">${tour.map((_,i)=>`<i class="${i===index?'active':''}"></i>`).join('')}</span><div>${index?'<button class="button" data-tour-back>Back</button>':''}<button class="button primary" data-tour-next>${index===4?'Enable guided mode':'Next →'}</button></div></div><button class="tour-skip" data-tour-skip>Skip tour</button>`);dialog.querySelector('[data-tour-back]')?.addEventListener('click',()=>showTour(index-1));dialog.querySelector('[data-tour-next]').onclick=()=>{if(index<4)showTour(index+1);else{closeDialog();callbacks.setGuided(true);}};dialog.querySelector('[data-tour-skip]').onclick=closeDialog;}
export function mountGuide({root,state,guided,busy,setGuided,uncertain=false}){callbacks={setGuided};
 const nav=document.querySelector('#workspace-navigation');nav.insertAdjacentHTML('beforeend',`<div class="guide-tools"><button class="guide-toggle ${guided?'enabled':''}" aria-pressed="${guided}" ${busy?'disabled':''}>${guided?'✓ Guided mode':'Guided mode'}</button><button class="tour-button" ${busy?'disabled':''}>Take a tour</button></div>`);nav.querySelector('.guide-toggle').onclick=()=>setGuided(!guided);nav.querySelector('.tour-button').onclick=()=>showTour();
 const team=root.querySelector('.team-mini');if(team){team.innerHTML=crew.map((a,i)=>`<button class="human-card" data-persona="${i}" ${busy?'disabled':''}>${portrait(i)}<span><strong>${a.name}<em>AI</em></strong><small>${a.role}</small><span class="human-hello">“${a.hello}”</span></span><b aria-hidden="true">↗</b></button>`).join('');}
 root.querySelectorAll('.agent').forEach(node=>{const strong=node.querySelector('strong');const i=crew.findIndex(a=>strong?.textContent.startsWith(a.name));if(i>=0){node.insertAdjacentHTML('afterbegin',`<button class="agent-face" data-persona="${i}" aria-label="Meet ${crew[i].name}, AI specialist">${portrait(i)}</button>`);}});
 root.querySelectorAll('[data-persona]').forEach(b=>b.onclick=()=>profile(Number(b.dataset.persona)));
 if(guided){const step=uncertain?{agent:3,title:'Confirm the latest status first.',body:'The last request did not return a confirmed result. Use Refresh status safely before approving or applying another action.',target:null}:guideStep(state),target=root.querySelector('.sheet')||root.querySelector('.desk-heading');if(target){const guide=document.createElement('section');guide.className='case-guide';guide.setAttribute('aria-label','Guided mode');guide.innerHTML=`${portrait(step.agent)}<div class="guide-message"><span class="eyebrow">${crew[step.agent].name.toUpperCase()} / GUIDED MODE</span><h2>${step.title}</h2><p>${step.body}</p>${state&&step.target?'<button class="guide-show">Show me where ↗</button>':''}</div><button class="guide-dismiss" aria-label="Turn off guided mode">×</button>`;target.before(guide);guide.querySelector('.guide-dismiss').onclick=()=>setGuided(false);guide.querySelector('.guide-show')?.addEventListener('click',()=>{const details=[...root.querySelectorAll('details.detail')].find(d=>d.querySelector('summary')?.textContent.startsWith(step.target));if(details){details.open=true;details.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});details.querySelector('summary').focus();}});}}
}
